function sessions({ host }: SlashContext): SlashOutcome {
  const list = host.app.getSessionManager().listSessions();
  if (!list.length) return reply("sessions", "No saved sessions yet.");
  const rows = list.slice(0, 10).map((s) => `${s.id === host.sessionId() ? "*" : " "} ${s.id}  ${s.updatedAt.slice(0, 19)}  ${oneLine(s.title)} · ${s.messageCount} messages`);
  return reply("sessions", [...rows, "", "Load one with /resume <id>."].join("\n"));
}

function save({ host, args }: SlashContext): SlashOutcome {
  if (host.app.getAgent().getMessages().length <= 1) return reply("save", "Nothing to save yet: the conversation is empty.", false);
  const previous = host.sessionId();
  if (args.trim()) host.setSessionId(args.trim());
  try {
    host.saveSession("Snapshot");
  } catch (err) {
    host.setSessionId(previous);
    throw err;
  }
  return reply("save", `Session saved as ${host.sessionId()}.`);
}

function resume({ host, args }: SlashContext): SlashOutcome {
  const wanted = args.trim();
  if (wanted) {
    const result = host.resumeSession(wanted);
    return reply("resume", result.message, result.ok);
  }
  // No argument: "the latest" is usually the session already open, so reloading it would only discard the live
  // conversation. Offer the most recent other one saved for this workspace (the session store is shared by every
  // workspace, and the loader refuses another workspace's record), trying older ones when a newer cannot be loaded.
  const here = comparableDir(host.app.getConfig().workspace);
  const resolved = new Map<string, string>();
  const dirOf = (dir: string) => resolved.get(dir) ?? (resolved.set(dir, comparableDir(dir)), resolved.get(dir)!);
  const candidates = host.app.getSessionManager().listSessions().filter((s) => s.id !== host.sessionId() && dirOf(s.workspace) === here);
  const skipped: string[] = [];
  for (const candidate of candidates) {
    let result: { ok: boolean; message: string };
    try {
      result = host.resumeSession(candidate.id);
    } catch (err) {
      result = { ok: false, message: errorText(err) };
    }
    if (result.ok) return reply("resume", skipped.length ? `${result.message} (skipped, could not be loaded: ${skipped.join(", ")})` : result.message, true);
    skipped.push(`${candidate.id} (${oneLine(result.message).slice(0, 100)})`);
  }
  const note = skipped.length ? ` Could not load: ${skipped.join(", ")}.` : "";
  return reply("resume", `There is no other saved session in this workspace to resume.${note} /sessions lists what is saved; /resume <id> loads one.`, false);
}

function comparableDir(dir: string | undefined): string {
  if (!dir) return "";
  try {
    return fs.realpathSync(dir);
  } catch {
        ...(turn ? { status: lifecycleStatusForTurn(turn) } : {}),
        ...(lastTurn ? { lastTurn } : {}),
      },
      agent.getWorkspacePathIdentity(),
    );
    return true;
  }

  private resumeSession(id?: string): { ok: boolean; message: string } {
    const manager = this.app.getSessionManager();
    let session;
    try {
      session = !id || id === "latest" ? manager.getLatestSession() : manager.loadSession(id);
    } catch (err: any) {
      return { ok: false, message: err.message };
    }
    if (!session) return { ok: false, message: `Session not found: ${id || "latest"}` };
    if (!Array.isArray(session.messages)) return { ok: false, message: `Session ${session.id} is unreadable: it has no message list.` };
    if (session.workspace && fs.existsSync(session.workspace)) this.setWorkspace(session.workspace);
    // The id changes together with the conversation, so a save after a partial restore never overwrites the previous session's record.
    this.sessionId = session.id;
    // What compaction replaced stays searchable after a resume (read_archive): only compactions this record committed.
    const archiveNotice = this.app.getAgent().restoreConversation(session, (committed) => this.app.getSessionManager().readArchivedHistory(session.id, committed));
    if (archiveNotice) this.emit({ type: "notice", text: archiveNotice });
    if (Array.isArray(session.activePlan)) this.app.getAgent().setActivePlan(session.activePlan);
    this.lastTurn = null;
    this.emitHistory(session.id, withHarnessProvenance(session.messages), session.lastTurn);
    // The count of the conversation is in the history header shown just before; this names the session.
    return { ok: true, message: `Resumed session ${session.id}.` };
  }

  /**
   * The resumed conversation for the client to show, in order: operator prompts, steering, the agent's replies, the
   * tools it called (name and subject; results stay in the session record), and the last turn's outcome. Nexus's own
   * prompts (continuation, recovery) and the runtime context appended to prompts are left out; text is redacted and
   * bounded, and only the latest HISTORY_ENTRIES entries are sent.
   */
  private emitHistory(sessionId: string, messages: ChatMessage[], lastTurn?: TurnResult | null): void {
    const text = (m: ChatMessage) => (typeof m.content === "string" ? m.content : Array.isArray(m.content) ? m.content.map((p: any) => (typeof p?.text === "string" ? p.text : "")).join("") : "");
    const entries: HistoryEntry[] = [];
    for (const m of messages) {
      const body = text(m);
      if (m.role === "user") {
        if (!body.trim() || isHarnessNote(m)) continue;
        // Steering is stored as "[Operator steering <id>]: text": shown as steering, without the marker.
        const typed = body.replace(/(\n+\[(?:Git Status|Active Plan): [^\n]*\])+\s*$/, "");
        if (typed.startsWith(STEERING_PREFIX)) entries.push({ role: "steering", text: typed.slice(typed.indexOf("]:") + 2).trim() });
        else entries.push({ role: "user", text: typed });
      } else if (m.role === "assistant") {
        if (body.trim()) entries.push({ role: "assistant", text: body });
        for (const call of m.tool_calls ?? []) {
          let args: Record<string, any> = {};
          try {
            args = JSON.parse(call.function.arguments || "{}");
          } catch {}
          entries.push({ role: "tool", tool: call.function.name, text: toolSubject(args, call.function.name) });
