    resumeSession: (id?: string) => {
      asked.push(id);
      const hit = list.find((x) => x.id === id) as any;
      if (hit?.throws) throw new Error("kaboom");
      return hit?.broken ? { ok: false, message: `Session not found: ${id}` } : { ok: true, message: `Resumed session ${id}.` };
